import SwiftUI
import SiliconModeKit

/// A provider's mark: the provider's real logo, drawn the way the brand presents it (its own colours
/// and ground, like its app icon) inside the round footprint faces, the HUD, settings and the menu
/// bar use. Silicons keep the Silicon mark; unknown providers get a monogram on a neutral disc.
///
/// Logo vectors are embedded (no runtime file or network IO) and parsed once by `SVGPathParser`. They
/// are generated from official logo files (product sites, brand kits, official repositories) by
/// `App/Resources/Logos/generate.py`; `App/Resources/Logos/SOURCES.md` lists every source and licence.
struct ProviderMark: View {
    let provider: String
    var size: CGFloat = 24

    var body: some View {
        let info = ProviderCatalog.info(for: provider)
        Group {
            if ProviderLogos.isSilicon(provider) {
                FaceASiliconMark(size: size)
            } else if let key = ProviderLogos.key(for: provider) {
                BrandMarkView(key: key, size: size)
            } else {
                MonogramMark(text: info.monogram.isEmpty ? String(provider.prefix(1)).uppercased() : info.monogram,
                             color: info.color, size: size)
            }
        }
        .accessibilityElement()
        .accessibilityLabel(info.name)
    }
}

/// A brand mark drawn into a `size`-point circle. Takes the brand key (not the mark) so SwiftUI can
/// tell two values apart cheaply and skip redrawing unchanged marks.
struct BrandMarkView: View {
    let key: String
    let size: CGFloat

    var body: some View {
        let mark = ProviderLogos.mark(key)
        Canvas { ctx, canvas in
            let s = min(canvas.width, canvas.height) / 100
            ctx.scaleBy(x: s, y: s)
            let disc = Path(ellipseIn: CGRect(x: 0, y: 0, width: 100, height: 100))
            ctx.clip(to: disc)
            mark.disc.fill(disc, in: &ctx, symbol: nil)
            for (i, layer) in mark.layers.enumerated() {
                layer.draw(in: &ctx, symbol: layer.isMesh ? ctx.resolveSymbol(id: i) : nil)
            }
        } symbols: {
            ForEach(Array(mark.layers.enumerated()), id: \.offset) { i, layer in
                if case .meshGradient(let m) = layer.paint {
                    MeshGradient(width: m.columns, height: m.rows, points: m.points, colors: m.colors)
                        .frame(width: max(1, m.rect.width * size / 100), height: max(1, m.rect.height * size / 100))
                        .tag(i)
                }
            }
        }
        .frame(width: size, height: size)
        .overlay(Circle().strokeBorder(mark.ring.color, lineWidth: max(0.5, size * 0.02)))
    }
}

/// Fallback for providers without a logo: the monogram in white on the catalog colour.
struct MonogramMark: View {
    let text: String
    let color: Color
    let size: CGFloat

    var body: some View {
        ZStack {
            Circle().fill(color)
            Circle().strokeBorder(.white.opacity(0.14), lineWidth: max(0.5, size * 0.02))
            Text(text)
                .font(Theme.allo(size * (text.count > 1 ? 0.36 : 0.46), .semibold))
                .tracking(-size * 0.01)
                .foregroundStyle(.white)
                .minimumScaleFactor(0.5)
        }
        .frame(width: size, height: size)
    }
}

// MARK: - Brand data model

/// A mark in a 100×100 box whose inscribed circle is the mark's footprint: a disc paint, then layers.
struct BrandMark: Sendable {
    enum Ring: Sendable {
        /// Hairline for dark grounds (keeps them apart from a dark background).
        case light
        /// Hairline for light grounds (keeps them apart from a light background).
        case dark

        var color: Color { self == .light ? .white.opacity(0.14) : .black.opacity(0.12) }
    }

    let disc: LogoPaint
    let ring: Ring
    let layers: [LogoLayer]
}

/// A gradient stop: offset, `RRGGBB`, alpha.
struct LogoStop: Sendable {
    let at: Double
    let hex: String
    let alpha: Double
    init(_ at: Double, _ hex: String, _ alpha: Double = 1) { self.at = at; self.hex = hex; self.alpha = alpha }
}

/// A mesh gradient over `rect` (in the 100-unit box), `columns × rows` colours, row by row.
struct LogoMesh: Sendable {
    let columns: Int
    let rows: Int
    let rect: CGRect
    let colors: [Color]

    var points: [SIMD2<Float>] {
        (0..<rows).flatMap { j in
            (0..<columns).map { i in SIMD2(Float(i) / Float(columns - 1), Float(j) / Float(rows - 1)) }
        }
    }
}

enum LogoPaint: Sendable {
    case solid(Color)
    case gradient(Gradient, CGPoint, CGPoint)
    case meshGradient(LogoMesh)

    static func color(_ hex: String, _ alpha: Double = 1) -> LogoPaint {
        .solid(alpha >= 1 ? Color(hex: hex) : Color(hex: hex).opacity(alpha))
    }

    static func linear(_ stops: [LogoStop], from: (CGFloat, CGFloat), to: (CGFloat, CGFloat)) -> LogoPaint {
        let g = Gradient(stops: stops.map { .init(color: Color(hex: $0.hex).opacity($0.alpha), location: $0.at) })
        return .gradient(g, CGPoint(x: from.0, y: from.1), CGPoint(x: to.0, y: to.1))
    }

    static func mesh(columns: Int, rows: Int, in r: (CGFloat, CGFloat, CGFloat, CGFloat), colors: [String]) -> LogoPaint {
        .meshGradient(LogoMesh(columns: columns, rows: rows, rect: CGRect(x: r.0, y: r.1, width: r.2, height: r.3),
                               colors: colors.map { Color(hex: $0) }))
    }

    var shading: GraphicsContext.Shading {
        switch self {
        case .solid(let c): .color(c)
        case .gradient(let g, let a, let b): .linearGradient(g, startPoint: a, endPoint: b)
        case .meshGradient(let m): .color(m.colors.first ?? .clear)
        }
    }

    /// Fills `path`; a mesh paint draws its resolved symbol clipped to the path.
    func fill(_ path: Path, in ctx: inout GraphicsContext, symbol: GraphicsContext.ResolvedSymbol?, evenOdd: Bool = false) {
        if case .meshGradient(let m) = self, let symbol {
            var c = ctx
            c.clip(to: path, style: FillStyle(eoFill: evenOdd))
            c.draw(symbol, in: m.rect)
        } else {
            ctx.fill(path, with: shading, style: FillStyle(eoFill: evenOdd))
        }
    }
}

/// One shape of a logo, in the 100-unit box.
struct LogoLayer: Sendable {
    let path: Path
    let paint: LogoPaint
    var evenOdd = false
    /// Stroke width and cap when the layer is stroked rather than filled.
    var stroke: (width: CGFloat, cap: CGLineCap)?

    static func fill(_ d: String, _ paint: LogoPaint, evenOdd: Bool = false) -> LogoLayer {
        LogoLayer(path: SVGPathParser.parse(d), paint: paint, evenOdd: evenOdd)
    }

    static func stroke(_ d: String, _ paint: LogoPaint, width: CGFloat, cap: CGLineCap = .round) -> LogoLayer {
        LogoLayer(path: SVGPathParser.parse(d), paint: paint, stroke: (width, cap))
    }

    var isMesh: Bool {
        if case .meshGradient = paint { return true }
        return false
    }

    func draw(in ctx: inout GraphicsContext, symbol: GraphicsContext.ResolvedSymbol?) {
        if let stroke {
            ctx.stroke(path, with: paint.shading, style: StrokeStyle(lineWidth: stroke.width, lineCap: stroke.cap, lineJoin: .round))
        } else {
            paint.fill(path, in: &ctx, symbol: symbol, evenOdd: evenOdd)
        }
    }
}

// MARK: - Provider → brand

enum ProviderLogos {
    static func isSilicon(_ provider: String) -> Bool { key(for: provider) == "silicon" }

    /// Maps a provider id (or alias / variant such as "antigravity-cli", "cursor-agent", "codex-cli")
    /// to a brand key, or nil when there is no logo for it.
    static func key(for provider: String) -> String? {
        let p = ProviderCatalog.canonicalID(provider).lowercased()
        if p.hasPrefix("silicon") { return "silicon" }
        if p.hasPrefix("claude") || p == "anthropic" { return "claude" }
        if p.hasPrefix("codex") || p.hasPrefix("openai") || p == "chatgpt" { return "openai" }
        if p.hasPrefix("antigravity") || p == "agy" { return "antigravity" }
        if p.hasPrefix("gemini") || p == "google" { return "gemini" }
        if p.hasPrefix("opencode") { return "opencode" }
        if p.hasPrefix("cursor") { return "cursor" }
        if p.contains("copilot") { return "copilot" }
        if p.hasPrefix("grok") || p == "xai" { return "grok" }
        if p.hasPrefix("qwen") { return "qwen" }
        if p.hasPrefix("windsurf") || p.hasPrefix("codeium") { return "windsurf" }
        if p.hasPrefix("zed") { return "zed" }
        if p.hasPrefix("factory") || p == "droid" { return "factory" }
        if p.hasPrefix("amazon-q") || p == "q" { return "amazonq" }
        if p.hasPrefix("kilo") { return "kilo" }
        if p.hasPrefix("roo") { return "roo" }
        if p.hasPrefix("augment") || p == "auggie" { return "augment" }
        if p.hasPrefix("t3") { return "t3" }
        if p.hasPrefix("letta") { return "letta" }
        if p.hasPrefix("kimi") { return "kimi" }
        if p.hasPrefix("kiro") { return "kiro" }
        let exact: Set<String> = ["pi", "omni", "hermes", "openclaw", "jules", "amp", "aider", "crush", "goose", "cline",
                                  "continue", "openhands", "codebuff", "plandex", "junie"]
        return exact.contains(p) ? p : nil
    }

    static func mark(_ key: String) -> BrandMark {
        switch key {
        case "claude": claude
        case "openai": openai
        case "opencode": opencode
        case "pi": pi
        case "hermes": hermes
        case "openclaw": openclaw
        case "antigravity": antigravity
        case "gemini": gemini
        case "jules": jules
        case "grok": grok
        case "cursor": cursor
        case "amp": amp
        case "factory": factory
        case "kiro": kiro
        case "aider": aider
        case "qwen": qwen
        case "crush": crush
        case "goose": goose
        case "copilot": copilot
        case "amazonq": amazonq
        case "kimi": kimi
        case "cline": cline
        case "roo": roo
        case "continue": continueDev
        case "windsurf": windsurf
        case "augment": augment
        case "letta": letta
        case "kilo": kilo
        case "openhands": openhands
        case "codebuff": codebuff
        case "plandex": plandex
        case "junie": junie
        case "t3": t3
        case "omni": omni
        case "zed": zed
        default: fallback
        }
    }

    static let fallback = BrandMark(disc: .color("7D7D7D"), ring: .light, layers: [])
}

